{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C05","C11","C12","C13","C08","C74","C68","C72","C75"],
  "contradictory_card_ids": ["C55","C61"],
  "prediction_basis_card_ids": ["C01","C05","C11","C12","C13","C08","C74"],
  "claims": [
    {
      "claim": "Transferable direct low-F outcomes in humans—FK3453 low/poor oral bioavailability (C01, C05), olcegepant %F<1 (C11), astemizole ~3% (C12), DX-9065 3% fasted (C13), and danavorexton poor requiring IV (C08)—affirmatively support F<20% for a lipophilic neutral heteroaromatic with first-pass/metabolic loss.",
      "card_ids": ["C01","C05","C11","C12","C13","C08"]
    },
    {
      "claim": "C74 directly states that ibrutinib is eliminated mainly by hepatic CYP metabolism, providing query-named mechanistic evidence for presystemic clearance; close BTK analogs zanubrutinib and acalabrutinib show high HLM intrinsic clearance (120 and 289.5 µL/min/mg) and CYP3A-mediated metabolism (C68, C72, C75).",
      "card_ids": ["C74","C68","C72","C75"]
    },
    {
      "claim": "L5 close-analog records C55 and C61 show high permeability and no appreciable efflux for a pyrazolopyrimidine acrylamide, supporting intestinal absorption but not systemic F; this does not overcome first-pass hepatic loss.",
      "card_ids": ["C55","C61"]
    },
    {
      "claim": "No direct human absolute F for the query is available; the low prediction is based on transferable low-F outcomes plus query-named hepatic metabolism, with residual uncertainty about exact F magnitude.",
      "card_ids": ["C74","C01","C05"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C74","C68","C72","C75"]
    }
  ],
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query is provided.",
    "No query-specific matched oral-versus-IV exposure data are available.",
    "C18 reports Fpod for compound 4p in monkeys, but its context card is ATP and the card does not confirm compound 4p is the query; direct applicability is uncertain.",
    "No query-specific HLM CLint value is given; C74 is qualitative and C68/C75 are for close analogs, not the query.",
    "Species differences in F (e.g., FK3453 high in dogs but low in humans) limit extrapolation from animal records.",
    "No query-specific solubility or dissolution data are available; high logP suggests solubility risk but is not measured."
  ],
  "decision_summary": "The query is a lipophilic neutral pyrazolopyrimidine acrylamide (ibrutinib). Transferable direct low-F contexts (FK3453, olcegepant, astemizole, DX-9065, danavorexton) and L6 evidence that ibrutinib is eliminated mainly by hepatic CYP metabolism (C74), with high HLM clearance in close BTK analogs (C68, C75), affirmatively support F<20%. L5 close-analog high permeability/no efflux supports absorption but does not overcome first-pass loss. Prediction: low."
}

